add_action( 'woocommerce_register_form', 'perfectpixel_reg_select_field', 20 );
add_filter( 'woocommerce_registration_errors', 'perfectpixel_reg_select_validate', 10, 3 );
add_action( 'woocommerce_created_customer', 'perfectpixel_reg_select_save' );
add_action( 'woocommerce_edit_account_form', 'perfectpixel_reg_select_account_field' );
add_action( 'woocommerce_save_account_details', 'perfectpixel_reg_select_save' );
add_action( 'show_user_profile', 'perfectpixel_reg_select_profile' );
add_action( 'edit_user_profile', 'perfectpixel_reg_select_profile' );

function perfectpixel_reg_select_options() {
	return array_values( array_filter( array_map( 'trim', explode( '|', '{{reg_select_options}}' ) ), 'strlen' ) );
}

function perfectpixel_reg_select_render( $current ) {
	$required = 'yes' === '{{reg_select_required}}';
	echo '<p class="woocommerce-form-row form-row form-row-wide"><label for="perfectpixel_reg_select">' . esc_html( '{{reg_select_label}}' ) . ( $required ? ' <span class="required">*</span>' : '' ) . '</label>';
	echo '<select name="perfectpixel_reg_select" id="perfectpixel_reg_select"' . ( $required ? ' required' : '' ) . '><option value="">—</option>';
	foreach ( perfectpixel_reg_select_options() as $option ) {
		echo '<option value="' . esc_attr( $option ) . '"' . selected( $current, $option, false ) . '>' . esc_html( $option ) . '</option>';
	}
	echo '</select></p>';
}

function perfectpixel_reg_select_field() {
	perfectpixel_reg_select_render( isset( $_POST['perfectpixel_reg_select'] ) ? sanitize_text_field( wp_unslash( $_POST['perfectpixel_reg_select'] ) ) : '' );
}

function perfectpixel_reg_select_account_field() {
	perfectpixel_reg_select_render( (string) get_user_meta( get_current_user_id(), 'perfectpixel_reg_select', true ) );
}

function perfectpixel_reg_select_value() {
	$value = isset( $_POST['perfectpixel_reg_select'] ) ? sanitize_text_field( wp_unslash( $_POST['perfectpixel_reg_select'] ) ) : '';
	return in_array( $value, perfectpixel_reg_select_options(), true ) ? $value : '';
}

function perfectpixel_reg_select_validate( $errors, $username, $email ) {
	if ( 'yes' === '{{reg_select_required}}' && '' === perfectpixel_reg_select_value() && ! is_checkout() ) {
		$errors->add( 'perfectpixel_reg_select', '{{reg_select_error}}' );
	}
	return $errors;
}

function perfectpixel_reg_select_save( $user_id ) {
	if ( isset( $_POST['perfectpixel_reg_select'] ) ) {
		update_user_meta( $user_id, 'perfectpixel_reg_select', perfectpixel_reg_select_value() );
	}
}

function perfectpixel_reg_select_profile( $user ) {
	if ( current_user_can( 'edit_users' ) ) {
		echo '<h2>' . esc_html( '{{reg_select_label}}' ) . '</h2><p>' . esc_html( (string) get_user_meta( $user->ID, 'perfectpixel_reg_select', true ) ) . '</p>';
	}
}
